fn solve(input: Vec<char>) -> Vec<char> {
    // Helper to check if a char is whitespace among the specified set
    fn is_ws(c: char) -> bool {
        c == ' ' || c == '\t' || c == '\n' || c == '\r'
    }

    let mut chars = input;

    // Step 1: Remove trailing '\n' if present
    if chars.last() == Some(&'\n') {
        chars.pop();
    }

    // Step 2: Repeatedly trim leading and trailing whitespace until neither end is whitespace
    // Since repeated trimming is equivalent to a single trim for these whitespace chars,
    // we can implement it using indices to avoid repeated costly operations.

    // Find first index from front that is not whitespace
    let start = chars.iter().position(|&c| !is_ws(c)).unwrap_or(chars.len());
    // Find last index from back that is not whitespace
    let end = chars.iter().rposition(|&c| !is_ws(c)).unwrap_or(0);

    // If start <= end, slice accordingly, else empty slice
    let trimmed: &[char] = if start <= end {
        &chars[start..=end]
    } else {
        &[]
    };

    // Step 3: Check password validity
    // Conditions:
    // - length at least 5
    // - contains at least one lowercase ASCII a-z
    // - contains at least one uppercase ASCII A-Z
    // - contains at least one digit 0-9

    let length_ok = trimmed.len() >= 5;
    let has_lower = trimmed.iter().any(|&c| ('a'..='z').contains(&c));
    let has_upper = trimmed.iter().any(|&c| ('A'..='Z').contains(&c));
    let has_digit = trimmed.iter().any(|&c| ('0'..='9').contains(&c));

    if length_ok && has_lower && has_upper && has_digit {
        "Correct\n".chars().collect()
    } else {
        "Too weak\n".chars().collect()
    }
}